use crate::parser::Symbols::Bar;


// All symbols generated by tokenizer for parser //////////////////////////////////////////////////
enum Symbols {
    Array,
    Begin,
    By,
    Case,
    Const,
    Continue,
    Definition,
    Div,
    Do,
    Else,
    Elsif,
    End,
    Exit,
    False,
    For,
    If,
    Import,
    In,
    Is,
    Loop,
    Mod,
    Module,
    Nil,
    Of,
    Or,
    Pointer,
    Proc,
    Procedure,
    Record,
    Repeat,
    Return,
    Then,
    To,
    True,
    Type,
    Until,
    Var,
    While,
    With,

    Minus,
    Comma,
    Semicolon,
    Colon,
    ColonAssign,
    Upto, // ..
    LeftParen,
    RightParen,
    LeftBracket,
    RightBracket,
    LeftCurly,
    RightCurly,
    Multiply,
    Slash,
    NotEqual,
    Arrow,
    Plus,
    Less,
    LessEqual,
    Equal,
    Greater,
    GreaterEqual,
    Bar,
    Tilde,
    Ambersand, // &
    Period,

    Ident,
    Number,
    String,
    HexString,
    HexChar,


    Unknown
}

// Abstract Syntax tree nodes generated by parser /////////////////////////////////////////////////
pub enum AST {
    RelationEqual(Box<AST>, Box<AST>),
    RelationNotEqual(Box<AST>, Box<AST>),
    RelationLess(Box<AST>, Box<AST>),
    RelationLessEqual(Box<AST>, Box<AST>),
    RelationGreater(Box<AST>, Box<AST>),
    RelationGreaterEqual(Box<AST>, Box<AST>),
    RelationIn(Box<AST>, Box<AST>),
    RelationIs(Box<AST>, Box<AST>),
    AddOperatorPlus(Box<AST>, Box<AST>),
    AddOperatorMinus(Box<AST>, Box<AST>),
    AddOperatorOr(Box<AST>, Box<AST>),
    UnaryPlus(Box<AST>),
    UnaryMinus(Box<AST>),
    MulOperatorMultiply(Box<AST>, Box<AST>),
    MulOperatorSlash(Box<AST>, Box<AST>),
    MulOperatorDiv(Box<AST>, Box<AST>),
    MulOperatorMod(Box<AST>, Box<AST>),
    MulOperatorAmbersAnd(Box<AST>, Box<AST>),
    FactorTilde(Box<AST>),
    LiteralTrue(u32, u32),
    LiteralFalse(u32, u32),
    LiteralNil(u32, u32),
    LiteralNumber(u32, u32, String),
    LiteralString(u32, u32, String),
    LiteralHexString(u32, u32, String),
    LiteralHexChar(u32, u32, String),
    Set(Vec<Box<AST>>),
    Element(Box<AST>, Box<AST>),
    DesignatorWithActualParameters(Box<AST>, Box<AST>),
    ExprList(Vec<Box<AST>>),
    ActualParameters(Option<Box<AST>>),
    Qualident(u32, u32, String, u32, u32, String),
    Name(u32, u32, String),
    Designator(Box<AST>, Box<AST>),
    Arrow,
    Index(Option<Box<AST>>),
    Call(Option<Box<AST>>),
    StatementSequence(Vec<Box<AST>>),
    Assignment(Box<AST>, Box<AST>),
    ProcedureCall(Box<AST>, Box<AST>),
    LoopStatement(Box<AST>),
    IfStatement(Box<AST>, Box<AST>, Vec<Box<AST>>, Option<Box<AST>>),
    ElsifStatement(Box<AST>, Box<AST>),
    ElseStatement(Box<AST>),
    ForStatement(Box<AST>, Box<AST>, Box<AST>, Option<Box<AST>>, Box<AST>),
    WithStatement(Vec<Box<AST>>, Option<Box<AST>>),
    WithElement(Box<AST>, Box<AST>), 
    Guard(Box<AST>, Box<AST>),
    WhileStatement(Box<AST>, Box<AST>, Option<Box<AST>>),
    RepeatStatement(Box<AST>, Box<AST>),
    ReturnStatement(Option<Box<AST>>),
    Exit,
    Continue
}


// Trait for Parser and Lexical analyzer methods //////////////////////////////////////////////////
pub trait ParseRules {
    fn new(source: String) -> Parser;
    fn advance(&mut self) -> ();

    /* Expression parse rules */
    fn expression(&mut self) -> Result<Box<AST>, String>;
    fn simple_expression(&mut self) -> Result<Box<AST>, String>;
    fn term(&mut self) -> Result<Box<AST>, String>;
    fn factor(&mut self) -> Result<Box<AST>, String>;
    fn literal(&mut self) -> Result<Box<AST>, String>;
    fn set(&mut self) -> Result<Box<AST>, String>;
    fn element(&mut self) -> Result<Box<AST>, String>;
    fn designator(&mut self) -> Result<Box<AST>, String>;
    fn selector(&mut self) -> Result<Box<AST>, String>;
    fn expr_list(&mut self) -> Result<Box<AST>, String>;
    fn actual_parameters(&mut self) -> Result<Box<AST>, String>;
    fn qualident(&mut self) -> Result<Box<AST>, String>;

    /* Statement parse rules */
    fn statement(&mut self) -> Result<Box<AST>, String>;
    fn if_statement(&mut self) -> Result<Box<AST>, String>;
    fn elsif_statement(&mut self) -> Result<Box<AST>, String>;
    fn else_statement(&mut self) -> Result<Box<AST>, String>;
    fn case_tatement(&mut self) -> Result<Box<AST>, String>;
    fn with_statement(&mut self) -> Result<Box<AST>, String>;
    fn with_element(&mut self, is_first: bool) -> Result<Box<AST>, String>;
    fn guard(&mut self) -> Result<Box<AST>, String>;
    fn loop_statement(&mut self) -> Result<Box<AST>, String>;
    fn exit_statement(&mut self) -> Result<Box<AST>, String>;
    fn return_statement(&mut self) -> Result<Box<AST>, String>;
    fn while_statement(&mut self) -> Result<Box<AST>, String>;
    fn repeat_statement(&mut self) -> Result<Box<AST>, String>;
    fn for_statement(&mut self) -> Result<Box<AST>, String>;
    fn assignment(&mut self) -> Result<Box<AST>, String>;
    fn statement_sequence(&mut self) -> Result<Box<AST>, String>;
}


// Parser for oberon //////////////////////////////////////////////////////////////////////////////
pub struct Parser {
    symbol: Symbols,
    line: u32,
    column: u32,
    buffer: String,
    source: String
}


// Oberon language parser and tokenizer methods ///////////////////////////////////////////////////
impl ParseRules for Parser {
    fn new(source: String) -> Self {
        Parser {
            symbol: Symbols::Unknown,
            line: 1,
            column: 1,
            buffer: "".to_string(),
            source: source
        }
    }

    fn advance(&mut self) -> () {

    }

    /* Expression rules */

    fn expression(&mut self) -> Result<Box<AST>, String> {
        let left = self.simple_expression()?; 
        match self.symbol {
            Symbols::Equal => {
                self.advance();
                Ok(Box::new(AST::RelationEqual(left, self.simple_expression()?)))
            },
            Symbols::NotEqual => {
                self.advance();
                Ok(Box::new(AST::RelationNotEqual(left, self.simple_expression()?)))
            },
            Symbols::Less => {
                self.advance();
                Ok(Box::new(AST::RelationLess(left, self.simple_expression()?)))
            },
            Symbols::LessEqual => {
                self.advance();
                Ok(Box::new(AST::RelationLessEqual(left, self.simple_expression()?)))
            },
            Symbols::Greater => {
                self.advance();
                Ok(Box::new(AST::RelationGreater(left, self.simple_expression()?)))
            },
            Symbols::GreaterEqual => {
                self.advance();
                Ok(Box::new(AST::RelationGreaterEqual(left, self.simple_expression()?)))
            },
            Symbols::In => {
                self.advance();
                Ok(Box::new(AST::RelationIn(left, self.simple_expression()?)))
            },
            Symbols::Is => {
                self.advance();
                Ok(Box::new(AST::RelationIs(left, self.simple_expression()?)))
            },
            _ =>
                Ok(left)
        }
    }

    fn simple_expression(&mut self) -> Result<Box<AST>, String> {
        let left = match self.symbol {
            Symbols::Plus => {
                self.advance();
                Box::new(AST::UnaryPlus(self.term()?))
            },
            Symbols::Minus => {
                self.advance();
                Box::new(AST::UnaryMinus(self.term()?))
            },
            _ => self.term()?
        };
        match self.symbol {
            Symbols::Plus => {
                self.advance();
                Ok(Box::new(AST::AddOperatorPlus(left, self.term()?)))
            },
            Symbols::Minus => {
                self.advance();
                Ok(Box::new(AST::AddOperatorMinus(left, self.term()?)))
            },
            Symbols::Or => {
                self.advance();
                Ok(Box::new(AST::AddOperatorOr(left, self.term()?)))
            },
            _ => Ok(left)
        }
    }

    fn term(&mut self) -> Result<Box<AST>, String> {
        let left = self.factor()?;
        match self.symbol {
            Symbols::Multiply => {
                self.advance();
                Ok(Box::new(AST::MulOperatorMultiply(left, self.factor()?)))
            },
            Symbols::Slash => {
                self.advance();
                Ok(Box::new(AST::MulOperatorSlash(left, self.factor()?)))
            },
            Symbols::Div => {
                self.advance();
                Ok(Box::new(AST::MulOperatorDiv(left, self.factor()?)))
            },
            Symbols::Mod => {
                self.advance();
                Ok(Box::new(AST::MulOperatorMod(left, self.factor()?)))
            },
            Symbols::Ambersand => {
                self.advance();
                Ok(Box::new(AST::MulOperatorAmbersAnd(left, self.factor()?)))
            },
            _ => Ok(left)
        }
    }

    fn factor(&mut self) -> Result<Box<AST>, String> {
        match self.symbol {
            Symbols::Tilde => {
                self.advance();
                Ok(Box::new(AST::FactorTilde(self.factor()?)))
            },
            Symbols::LeftParen => {
                self.advance();
                let left = self.expression()?;
                match self.symbol {
                    Symbols::RightParen => {
                        self.advance();
                        Ok(left)
                    },
                    _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing closing `)` in expression.", self.line, self.column, self.source))
                }
            },
            Symbols::Ident => {
                let left = self.designator()?;
                match self.symbol {
                    Symbols::LeftParen => {
                        let right = self.actual_parameters()?;
                        Ok(Box::new(AST::DesignatorWithActualParameters(left, right)))
                    },
                    _ => Ok(left)
                }
            }
            _ => self.literal()
        }
    }

    fn literal(&mut self) -> Result<Box<AST>, String> {
        let line = self.line; let col = self.column;
        match self.symbol {
            Symbols::Number => {
                let buffer = self.buffer.clone();
                self.advance();
                Ok(Box::new(AST::LiteralNumber(line, col, buffer)))
            },
            Symbols::String => {
                let buffer = self.buffer.clone();
                self.advance();
                Ok(Box::new(AST::LiteralString(line, col, buffer)))
            },
            Symbols::HexString => {
                let buffer = self.buffer.clone();
                self.advance();
                Ok(Box::new(AST::LiteralHexString(line, col, buffer)))
            },
            Symbols::HexChar => {
                let buffer = self.buffer.clone();
                self.advance();
                Ok(Box::new(AST::LiteralHexChar(line, col, buffer)))
            },
            Symbols::Nil => {
                self.advance();
                Ok(Box::new(AST::LiteralNil(line, col)))
            },
            Symbols::True => {
                self.advance();
                Ok(Box::new(AST::LiteralTrue(line, col)))
            },
            Symbols::False => {
                self.advance();
                Ok(Box::new(AST::LiteralFalse(line, col)))
            },
            Symbols::LeftCurly => {
                self.set()
            },
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing literal.", self.line, self.column, self.source))
        }
    }

    fn set(&mut self) -> Result<Box<AST>, String> {
        let mut elements = Vec::<Box<AST>>::new();
        self.advance();
        match self.symbol {
            Symbols::RightCurly => {
                self.advance();
                Ok(Box::new(AST::Set(elements)))
            },
            _ => {
                elements.push(self.element()?);
                loop {
                    match self.symbol {
                        Symbols::Comma => {
                            self.advance();
                            elements.push(self.element()?);
                        },
                        _ => break
                    }
                }
                match self.symbol {
                    Symbols::RightCurly => {
                        self.advance();
                        Ok(Box::new(AST::Set(elements)))
                    },
                    _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing closing parenthesis in set.", self.line, self.column, self.source))
                }
            }
        }
    }

    fn element(&mut self) -> Result<Box<AST>, String> {
        let left = self.expression()?;
        match self.symbol {
            Symbols::Upto => {
                self.advance();
                Ok(Box::new(AST::Element(left, self.expression()?)))
            },
            _ => Ok(left)
        }
    }

    fn designator(&mut self) -> Result<Box<AST>, String> {
        let left = self.qualident()?;
        match self.symbol {
            Symbols::Period |
            Symbols::Arrow |
            Symbols::LeftBracket |
            Symbols::LeftParen => {
                let right = self.selector()?;
                Ok(Box::new(AST::Designator(left, right)))
            },
            _ => Ok(left)
        }
    }

    fn selector(&mut self) -> Result<Box<AST>, String> {
        match self.symbol {
            Symbols::Arrow => {
                self.advance();
                Ok(Box::new(AST::Arrow))
            },
            Symbols::Period => {
                self.advance();
                match self.symbol {
                    Symbols::Ident => {
                        let line = self.line; let col = self.column; let buffer = self.buffer.clone();
                        self.advance();
                        Ok(Box::new(AST::Name(line, col, buffer)))
                    },
                    _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing Name after `.` in selector.", self.line, self.column, self.source))
                }
            },
            Symbols::LeftBracket => {
                self.advance();
                match self.symbol {
                    Symbols::RightBracket => {
                        self.advance();
                        Ok(Box::new(AST::Index(None)))
                    },
                    _ => {
                        let node = self.expr_list()?;
                        match self.symbol {
                            Symbols::RightBracket => {
                                self.advance();
                                Ok(Box::new(AST::Index(Some(node))))
                            },
                            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `]` in indexing.", self.line, self.column, self.source))
                        }
                    }
                }
            },
            _ => {
                /* Must be `(´ */
                self.advance();
                match self.symbol {
                    Symbols::RightParen => {
                        self.advance();
                        Ok(Box::new(AST::Call(None)))
                    },
                    _ => {
                        let node = self.qualident()?;
                        match self.symbol {
                            Symbols::RightParen => {
                                self.advance();
                                Ok(Box::new(AST::Call(Some(node))))
                            },
                            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `]` in indexing.", self.line, self.column, self.source))
                        }
                    }
                }
            }
        }
    }

    fn expr_list(&mut self) -> Result<Box<AST>, String> {
        let left = self.expression()?;
        match self.symbol {
            Symbols::Comma => {
                let mut elements = Vec::<Box<AST>>::new();
                elements.push(left);
                self.advance();
                loop {
                    elements.push(self.expression()?);
                    match self.symbol {
                        Symbols::Comma => self.advance(),
                        _ => { break; }
                    }
                }
                Ok(Box::new(AST::ExprList(elements)))
            },
            _ => Ok(left)
        }
    }

    fn actual_parameters(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        match self.symbol {
            Symbols::RightParen => {
                self.advance();
                Ok(Box::new(AST::ActualParameters(None)))
            },
            _ => {
                let left = self.expr_list()?;
                match self.symbol {
                    Symbols::RightParen => {
                        self.advance();
                        Ok(Box::new(AST::ActualParameters(Some(left))))
                    },
                    _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing closing parenthesis in parameters.", self.line, self.column, self.source))
                }
            }
        }
    }

    fn qualident(&mut self) -> Result<Box<AST>, String> {
        let first_line = self.line; let first_col = self.column; let first_name = self.buffer.clone();
        self.advance();
        match self.symbol {
            Symbols::Period => {
                self.advance();
                match self.symbol {
                    Symbols::Ident => {
                        let second_line = self.line; let second_col = self.column; let second_name = self.buffer.clone();
                        self.advance();
                        Ok(Box::new(AST::Qualident(first_line, first_col, first_name, second_line, second_col, second_name)))
                    },
                     _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing Name after `.`in qualident.", self.line, self.column, self.source))   
                }
            },
            _ => Ok(Box::new(AST::Name(first_line, first_col, first_name)))
        }
    }

    /* Statement rules */

    fn statement(&mut self) -> Result<Box<AST>, String> {
        match self.symbol {
            Symbols::If => self.if_statement(),
            Symbols::Case => self.case_tatement(),
            Symbols::With => self.with_statement(),
            Symbols::Loop => self.loop_statement(),
            Symbols::Exit => self.exit_statement(),
            Symbols::Return => self.return_statement(),
            Symbols::While => self.while_statement(),
            Symbols::Repeat => self.repeat_statement(),
            Symbols::For => self.for_statement(),
            Symbols::Ident => self.assignment(),
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing valid statement(s).", self.line, self.column, self.source))
        }
    }

    fn if_statement(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        let left = self.expression()?;
        match self.symbol {
            Symbols::Then => {
                self.advance();
                let right = self.statement_sequence()?;
                let mut nodes = Vec::<Box<AST>>::new();
                loop {
                    match self.symbol {
                        Symbols::Elsif => {
                            nodes.push(self.elsif_statement()?);
                        },
                        _ => { break; }
                    }
                }
                let node = match self.symbol {
                    Symbols::Else => {
                        Some(self.else_statement()?)
                    },
                    _ => None
                };

                Ok(Box::new(AST::IfStatement(left, right, nodes, node)))
            },
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `THEM` in if statement.", self.line, self.column, self.source))
        }
    }

    fn elsif_statement(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        let left = self.expression()?;
        match self.symbol {
            Symbols::Then => {
                self.advance();
                let right = self.statement_sequence()?;
                Ok(Box::new(AST::ElsifStatement(left, right)))
            },
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `THEM` in elsif statement.", self.line, self.column, self.source))
        }
    }

    fn else_statement(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        Ok(Box::new(AST::ElseStatement(self.statement_sequence()?)))
    }

    fn case_tatement(&mut self) -> Result<Box<AST>, String> {
        todo!()
    }

    fn with_statement(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        let mut elements = Vec::<Box<AST>>::new();
        elements.push(self.with_element(true)?);
        loop {
            match self.symbol {
                Symbols::Else |
                Symbols::End => {
                    break;
                },
                _ => {
                    elements.push(self.with_element(false)?);
                }
            }
        }

        let element = match self.symbol {
            Symbols::Else => {
                Some(self.else_statement()?)
            }
            _ => None
        };

        match self.symbol {
            Symbols::End => {
                self.advance();
                Ok(Box::new(AST::WithStatement(elements, element)))
            },
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `END` in with statement.", self.line, self.column, self.source))
        }
    }

    fn with_element(&mut self, is_first: bool) -> Result<Box<AST>, String> {
        match self.symbol {
            Symbols::Bar => {
                self.advance();
            },
            _ => {
                match is_first {
                    true => (),
                    _ => return Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `|` in `with` statement.", self.line, self.column, self.source))
                }
            }
        }
        let left = self.guard()?;
        match self.symbol {
            Symbols::Do => {
                self.advance();
                Ok(Box::new(AST::WithElement(left, self.statement_sequence()?)))
            },
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `DO` in `with` statement.", self.line, self.column, self.source))
        }
    }

    fn guard(&mut self) -> Result<Box<AST>, String> {
        let left = self.expression()?;
        match self.symbol {
            Symbols::Colon => {
                self.advance();
                Ok(Box::new(AST::Guard(left, self.qualident()?)))
            },
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `:` in guard of `with` statement.", self.line, self.column, self.source))
        }
    }

    fn loop_statement(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        let node = self.statement_sequence()?;
        match self.symbol {
            Symbols::End => {
                self.advance();
                Ok(Box::new(AST::LoopStatement(node)))
            },
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `END` in loop statement.", self.line, self.column, self.source))
        }
    }

    fn exit_statement(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        Ok(Box::new(AST::Exit))
    }

    fn return_statement(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        match self.symbol {
            Symbols::Semicolon |
            Symbols::If |
            Symbols::Elsif |
            Symbols::Else |
            Symbols::Case |
            Symbols::With |
            Symbols::Loop |
            Symbols::Exit |
            Symbols::Continue |
            Symbols::Return |
            Symbols::While |
            Symbols::Repeat |
            Symbols::For |
            Symbols::End => Ok(Box::new(AST::ReturnStatement(None))),
            _ => Ok(Box::new(AST::ReturnStatement(Some(self.expression()?))))
        }
    }

    fn while_statement(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        let left = self.expression()?;
        match self.symbol {
            Symbols::Do => {
                self.advance();
                let right = self.statement_sequence()?;
                let next = match self.symbol {
                    Symbols::Else => {
                        Some(self.else_statement()?)
                    },
                    _ => None
                };
                match self.symbol {
                    Symbols::End => {
                        self.advance();
                        Ok(Box::new(AST::WhileStatement(left, right, next)))
                    },
                    _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `END` in while statement.", self.line, self.column, self.source))
                }
            },
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `DO` in while statement.", self.line, self.column, self.source))
        }
    }

    fn repeat_statement(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        let left = self.statement_sequence()?;
        match self.symbol {
            Symbols::Until => {
                self.advance();
                Ok(Box::new(AST::RepeatStatement(left, self.expression()?)))
            },
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `UNTIL` in repeat statement.", self.line, self.column, self.source))
        }
        
    }

    fn for_statement(&mut self) -> Result<Box<AST>, String> {
        self.advance();
        match self.symbol {
            Symbols::Ident => {
                let name = Box::new(AST::Name(self.line, self.column, self.buffer.clone()));
                self.advance();
                match self.symbol {
                    Symbols::ColonAssign => {
                        self.advance();
                        let left = self.expression()?;
                        match self.symbol {
                            Symbols::To => {
                                self.advance();
                                let right = self.expression()?;
                                let next = match self.symbol {
                                    Symbols::By => {
                                        self.advance();
                                        Some(self.expression()?)
                                    },
                                    _ => None
                                };
                                match self.symbol {
                                    Symbols::Do => {
                                        self.advance();
                                        let body = self.statement_sequence()?;
                                        match self.symbol {
                                            Symbols::End => {
                                                self.advance();
                                                Ok(Box::new(AST::ForStatement(name, left, right, next, body)))
                                            },
                                            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `END` in `FOR` statement.", self.line, self.column, self.source))
                                        }
                                    },
                                    _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `DO` in `FOR` statement.", self.line, self.column, self.source))
                                }                        
                            },
                            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `TO` in `FOR` statement.", self.line, self.column, self.source))
                        }
                    },
                    _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing `:=` in `FOR` statement.", self.line, self.column, self.source))
                }
            },
            _ => Err(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing Name in `FOR` statement.", self.line, self.column, self.source))
        }
    }

    fn assignment(&mut self) -> Result<Box<AST>, String> {
        let left = self.designator()?;
        match self.symbol {
            Symbols::ColonAssign => {
                self.advance();
                Ok(Box::new(AST::Assignment(left, self.expression()?)))
            },
            Symbols::LeftParen => {
                let right = self.actual_parameters()?;
                Ok(Box::new(AST::ProcedureCall(left, right)))
            },
            _ => {
                Ok(left) /* procedure call without argument */
            }
        }
    }

    fn statement_sequence(&mut self) -> Result<Box<AST>, String> {
        let mut nodes = Vec::<Box<AST>>::new();
        nodes.push(self.statement()?);

        loop {
            match self.symbol {
                Symbols::Semicolon => {
                    self.advance();
                },
                _ => ()
            }
            match self.symbol {
                Symbols::Ident |
                Symbols::If |
                Symbols::Case |
                Symbols::With |
                Symbols::Loop |
                Symbols::Exit |
                Symbols::Return |
                Symbols::While |
                Symbols::Repeat |
                Symbols::For => {
                    nodes.push(self.statement()?)
                },
                _ => {
                    break
                }
            }
        }

        match nodes.len() {
             1 => nodes.pop().ok_or(format!("Syntax Error! At line: {}, column: {} in file: {} - Missing statement in sequence.", self.line, self.column, self.source)),
             _ => Ok(Box::new(AST::StatementSequence(nodes)))
        }
    }

    
}


